FILES = {'experiments/day18_evidence_caveats.py': '"""Add estimator and cross-backbone disclosure to the evidence-refreshed draft."""\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport pandas as pd\nfrom experiments.day5_report import markdown_table\n\n\ndef replace_once(text, old, new):\n    assert text.count(old) == 1, \'Inspect an independently changed draft before editing\'\n    return text.replace(old, new, 1)\n\n\ndef main():\n    paper = Path(\'notes/paper_working_draft.md\')\n    previous = hashlib.sha256(paper.read_bytes()).hexdigest()\n    receipt = json.loads(Path(\'notes/manuscript_refresh_receipt.json\').read_text())\n    assert receipt[\'new_manuscript_sha256\'] == previous\n    text = paper.read_text()\n    text = replace_once(text,\n        \'rather than a need for additional representation capacity.\',\n        \'rather than a need for additional low-rank adaptation capacity.\')\n    text = replace_once(text,\n        \'The head-only control keeps all LoRA outputs exactly zero and trains only private classifiers.\',\n        \'The control named head-only keeps all LoRA outputs exactly zero and trains \'\n        \'the private pre-classifier/classifier stack. Its hidden pre-classifier is \'\n        \'a learned representation transform; this control rules out a need for \'\n        \'LoRA in the observed allocation decisions, not all hidden representation learning.\')\n    text = replace_once(text,\n        \'Matched component interventions show substantial classifier-reset effects on a BANKING recurrence stream.\',\n        \'Matched component interventions show classifier-reset effects at the original BANKING \'\n        \'allocation windows; the broader all-mature-batch audit separately measures effects \'\n        \'across the continuing trajectory.\')\n    text = replace_once(text,\n        \'Across five fresh seeds and two orders, a classifier-only allocator makes the same structural decisions as the full adapter allocator on BANKING, although training low-rank parameters improves prediction.\',\n        \'Across five development training seeds and two orders, a classifier-only allocator \'\n        \'makes the same structural decisions as the full adapter allocator on BANKING, \'\n        \'although training low-rank parameters improves prediction. The BERT transfer \'\n        \'diagnostic also preserves allocation decisions under its declared recipe.\')\n    anchor = (\'The interval unit is a paired training seed; \'\n              \'the fixed development examples do not supply population-sampling uncertainty.\')\n    text = replace_once(text, anchor, anchor + \'\\n\\n\'\n        \'The all-mature-batch marginal effects average all eight settings of the other \'\n        \'three reset factors and all eligible batches. They are a different estimand \'\n        \'from fresh-package versus best-feasible-reuse advantage at allocation windows. \'\n        \'Their signs need not agree. These measurements do not imply that resetting \'\n        \'a trained classifier generally improves prediction. Conditional contrasts \'\n        \'retain the artificial inherited-state/reset-weight combinations; useful \'\n        \'deployment recipes require separate closed-loop experiments.\')\n    anchor = (\'classifier together. It uses a single linear classifier rather than the DistilBERT \'\n              \'trainable pre-classifier/classifier stack, but is not a causal isolation of classifier \'\n              \'design or a tuned BERT performance comparison.\')\n    differences = pd.read_csv(\'results/day16_bert_paired_differences.csv\')\n    assert len(differences) == 6 and set(differences.seed_clusters) == {5}\n    text = replace_once(text, anchor, anchor + \'\\n\\n\'\n        \'All cross-backbone prediction differences are reported below. Negative \'\n        \'values indicate lower BERT accuracy. The cross-backbone changes are joint \'\n        \'changes in architecture and initialized packages, not an optimized \'\n        \'performance comparison or a classifier-only causal attribution.\\n\\n\'\n        + markdown_table(differences))\n    qc = json.loads(Path(\'notes/factorial_receipt_integrity_final.json\').read_text())\n    assert not qc[\'failed\']\n    anchor = \'## Figures and result sources\'\n    text = replace_once(text, anchor,\n        \'## Independent saved-receipt quality control\\n\\n\'\n        f\'A read-only check of {len(qc["passed"])} completed observer trajectories \'\n        \'verified every eligible mature batch, the actual active source, all sixteen \'\n        \'intervention cells and both query folds, weight/state receipt isolation, \'\n        \'bitwise invariance of initial predictions to optimizer-state interventions, \'\n        \'and query-loss/component identities. This additional quality-control check \'\n        \'was added after the first observer outcomes. It changes neither the frozen \'\n        \'experiments nor their contrast definitions and is not a new scientific \'\n        \'replication. Earlier and final receipts are preserved.\\n\\n\' + anchor)\n    retention = pd.read_csv(\'results/day18_retention_paired_differences.csv\')\n    drops = retention[retention.metric == \'maximum_seen_checkpoint_drop\']\n    assert len(drops) >= 6\n    text = replace_once(text, anchor,\n        \'## Secondary deployed-retention analysis\\n\\n\'\n        \'An analysis added after primary outcomes uses all five saved segment-end \'\n        \'checkpoints and all three original deployment rules. It compares fixed-memory \'\n        \'adaptive trajectories with the frozen static reference and every available \'\n        \'pilot-selected static rank on exactly paired streams. For each concept, the \'\n        \'observed checkpoint drop is its maximum accuracy after first exposure minus \'\n        \'its final accuracy; the statistic is averaged over concepts. Positive \'\n        \'adaptive-minus-static differences below indicate more drop for the adaptive \'\n        \'predictor. These are descriptive five-seed development summaries, not \'\n        \'retention guarantees or independently confirmed hypotheses.\\n\\n\'\n        + markdown_table(drops) + \'\\n\\n\'\n        \'The full report also retains final accuracy, the mean seen-concept \'\n        \'checkpoint accuracy and final-minus-first-exposure accuracy. Recurrence \'\n        \'contributes to the latter, so it is not standard backward transfer for \'\n        \'a nonrecurring task sequence. Fixed-memory learned routers have only final \'\n        \'reload measurements; their temporal retention is unavailable and is not \'\n        \'imputed. Definitions, all comparisons and source hashes are in \'\n        \'`notes/day18_deployment_retention_results.md`.\\n\\n\' + anchor)\n    control_path = Path(\'notes/day19_linear_classifier_execution.json\')\n    if control_path.exists():\n        control = json.loads(control_path.read_text())\n        complete = sum(r[\'phase\'] == \'diagnostic\' and r[\'status\'] == \'completed\' for r in control[\'jobs\'])\n        pairs = pd.read_csv(\'results/day19_linear_classifier_allocation_pairs.csv\') if complete else pd.DataFrame()\n        differences = pd.read_csv(\'results/day19_linear_classifier_prediction_differences.csv\') if complete else pd.DataFrame()\n        text = replace_once(text, anchor,\n            \'## Within-backbone output-classifier control\\n\\n\'\n            \'The original head-only DistilBERT control includes a learned hidden \'\n            \'pre-classifier. A separately declared development extension freezes \'\n            \'that layer in both LoRA-plus-output-classifier and output-classifier-only \'\n            \'learning. It retains the DistilBERT backbone, initialization, stream, \'\n            \'allocator, optimizer rate, clipping and memory condition. It removes \'\n            \'hidden pre-classifier learning and its optimizer state together; it \'\n            \'is not a weight-versus-state factorial for that layer. PEFT stores \'\n            \'dormant pre-classifier copies, which remain counted in storage.\\n\\n\'\n            f\'The extension completed {complete}/20 research trajectories and \'\n            f\'{len(pairs)}/10 allocation pairs. Its unchanged-wrapper replay and \'\n            \'tiny CPU/CUDA intervention gates precede the research runs. The \'\n            \'following tables retain every completed pair and every original \'\n            \'prediction rule; these are repeatedly examined development streams, \'\n            \'not untouched confirmation or tuned competitive performance.\\n\\n\'\n            + markdown_table(pairs) + \'\\n\\n\' + markdown_table(differences) + \'\\n\\n\'\n            \'All deviations from the trainable-stack references, each trajectory \'\n            \'and stored frozen versus output-classifier parameters are in \'\n            \'`notes/day19_linear_classifier_results.md`.\\n\\n\' + anchor)\n    paper.write_text(text)\n    Path(\'notes/manuscript_evidence_caveats_receipt.json\').write_text(json.dumps({\n        \'previous_manuscript_sha256\': previous,\n        \'new_manuscript_sha256\': hashlib.sha256(paper.read_bytes()).hexdigest(),\n        \'saved_observers_independently_checked\': len(qc[\'passed\']),\n        \'scope\': \'estimator distinction, full cross-backbone results, post-outcome quality-control disclosure\',\n        \'training_outputs_modified\': False}, indent=2) + \'\\n\')\n    print(\'EVIDENCE_ESTIMATOR_AND_TRANSFER_CAVEATS_SAVED\', flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day18_deployment_retention.py': '"""Secondary development retention summaries from saved deployed predictions.\n\nAdded after primary development outcomes. No new training, final-test use, or\nchanges to the pilot-only learning-rate selection. Recurrence deltas are not\nthe standard backward-transfer statistic for a nonrecurring task sequence.\n"""\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nfrom experiments.day5_report import markdown_table\nfrom experiments.day6_diagnostic_report import interval\n\nRULES = [\'last_active\', \'uniform_probability\', \'frozen_centroid\']\nMETRICS = [\'final_macro_accuracy\', \'mean_seen_checkpoint_accuracy\',\n           \'maximum_seen_checkpoint_drop\', \'final_minus_first_exposure\']\n\n\ndef summarize(folder):\n    p = json.loads((folder / \'provenance.json\').read_text())\n    s = json.loads((folder / \'summary.json\').read_text())\n    route = pd.read_csv(folder / \'routing.csv\')\n    d = pd.read_csv(folder / \'label_free_eval.csv\')\n    assert s[\'status\'] == \'completed\' and s[\'steps\'] == 80 and len(route) == 80\n    endpoints = set(route.groupby(\'segment\').step.max())\n    assert len(endpoints) == 5 and max(endpoints) == 80\n    assert set(d.step) == endpoints and set(d.rule) == set(RULES)\n    assert set(d.concept) == {\'A\', \'B\', \'C\'} and len(d) == 45\n    assert np.isfinite(d.accuracy).all() and d.accuracy.between(0, 1).all()\n    concepts, summaries = [], []\n    for rule, predictions in d.groupby(\'rule\'):\n        for step, checkpoint in predictions.groupby(\'step\'):\n            assert len(checkpoint) == 3\n            seen = set(route.loc[route.step <= step, \'concept\'])\n            assert set(checkpoint.loc[checkpoint.seen_concept, \'concept\']) == seen\n        first_steps = {}\n        for concept, group in predictions.groupby(\'concept\'):\n            assert len(group) == 5 and group.n.nunique() == 1\n            first = int(group.loc[group.checkpoint.str[0] == concept, \'step\'].min())\n            first_steps[concept] = first\n            final = float(group.loc[group.step == 80, \'accuracy\'].iloc[0])\n            initial = float(group.loc[group.step == first, \'accuracy\'].iloc[0])\n            best = float(group.loc[group.step >= first, \'accuracy\'].max())\n            concepts.append({\'rule\': rule, \'concept\': concept, \'first_exposure_checkpoint\': first,\n                \'first_exposure_accuracy\': initial, \'final_accuracy\': final,\n                \'maximum_seen_accuracy\': best, \'maximum_seen_checkpoint_drop\': best-final,\n                \'final_minus_first_exposure\': final-initial})\n        part = pd.DataFrame([r for r in concepts if r[\'rule\'] == rule])\n        seen_curve = predictions[predictions.seen_concept].groupby(\'step\').accuracy.mean()\n        assert len(seen_curve) == 5\n        summaries.append({\'rule\': rule, \'final_macro_accuracy\': part.final_accuracy.mean(),\n            \'mean_seen_checkpoint_accuracy\': seen_curve.mean(),\n            \'maximum_seen_checkpoint_drop\': part.maximum_seen_checkpoint_drop.mean(),\n            \'final_minus_first_exposure\': part.final_minus_first_exposure.mean()})\n    return p, summaries, concepts\n\n\ndef main():\n    rows, concept_rows, comparisons, coverage, hashes = [], [], [], [], {}\n    selected_path = Path(\'notes/day17_static_rate_selection.json\')\n    selection = json.loads(selected_path.read_text()) if selected_path.exists() else None\n    for regime in [\'banking\', \'amazon\']:\n        for seed in range(2027, 2032):\n            for order in [\'canonical\', \'b_first\']:\n                names = {\'adaptive\': f\'day8_{regime}_private_cau_seed{seed}_{order}_fixed512\',\n                         \'static_rank8_frozen\': f\'day6_{regime}_private_single_seed{seed}_{order}\'}\n                if regime == \'banking\' and selection:\n                    for rank in [8, 96]:\n                        rate = selection[\'selected_rates\'][str(rank)]\n                        names[\'static_rank\' + str(rank) + \'_tuned\'] = (\n                            f\'day17_confirm_rank{rank}_lr{int(round(rate*1e6))}_seed{seed}_{order}\')\n                groups, streams = {}, {}\n                for method, name in names.items():\n                    folder = Path(\'results\', name)\n                    if not (folder / \'summary.json\').exists() or json.loads((folder / \'summary.json\').read_text())[\'status\'] != \'completed\':\n                        coverage.append({\'regime\': regime, \'seed\': seed, \'order\': order,\n                                         \'method\': method, \'status\': \'missing_or_incomplete\'})\n                        continue\n                    p, values, concepts = summarize(folder)\n                    streams[method] = p[\'stream_sha256\']\n                    groups[method] = {r[\'rule\']: r for r in values}\n                    metadata = {\'regime\': regime, \'seed\': seed, \'order\': order, \'method\': method, \'run\': name}\n                    rows.extend({**metadata, **r} for r in values)\n                    concept_rows.extend({**metadata, **r} for r in concepts)\n                    coverage.append({**metadata, \'status\': \'completed\'})\n                    for name in [\'provenance.json\', \'routing.csv\', \'label_free_eval.csv\']:\n                        hashes[str(folder / name)] = hashlib.sha256((folder / name).read_bytes()).hexdigest()\n                assert len(set(streams.values())) <= 1, \'Unpaired deployed-retention streams\'\n                if \'adaptive\' in groups:\n                    for method in sorted(set(groups) - {\'adaptive\'}):\n                        for rule in RULES:\n                            for metric in METRICS:\n                                comparisons.append({\'regime\': regime, \'seed\': seed, \'order\': order,\n                                    \'comparison\': \'adaptive_minus_\' + method, \'rule\': rule, \'metric\': metric,\n                                    \'difference\': groups[\'adaptive\'][rule][metric] - groups[method][rule][metric]})\n    summary_rows, seed_rows = [], []\n    if comparisons:\n        frame = pd.DataFrame(comparisons)\n        for key, group in frame.groupby([\'regime\', \'comparison\', \'rule\', \'metric\']):\n            complete = group.groupby(\'seed\').filter(lambda g: len(g) == 2 and set(g.order) == {\'canonical\', \'b_first\'})\n            values = complete.groupby(\'seed\').difference.mean()\n            if len(values):\n                summary_rows.append(dict(zip([\'regime\', \'comparison\', \'rule\', \'metric\'], key)) | interval(values))\n                seed_rows.extend(dict(zip([\'regime\', \'comparison\', \'rule\', \'metric\'], key)) |\n                                 {\'seed\': seed, \'difference\': value} for seed, value in values.items())\n        frame.to_csv(\'results/day18_retention_trajectory_comparisons.csv\', index=False)\n    summary = pd.DataFrame(summary_rows)\n    pd.DataFrame(rows).to_csv(\'results/day18_retention_trajectory_metrics.csv\', index=False)\n    pd.DataFrame(concept_rows).to_csv(\'results/day18_retention_concept_metrics.csv\', index=False)\n    pd.DataFrame(coverage).to_csv(\'results/day18_retention_coverage.csv\', index=False)\n    pd.DataFrame(seed_rows).to_csv(\'results/day18_retention_seed_values.csv\', index=False)\n    summary.to_csv(\'results/day18_retention_paired_differences.csv\', index=False)\n    report = [\'# Secondary deployed-retention development analysis\', \'\',\n        \'Added after primary development outcomes. Uses saved full-output-space predictions, \'\n        \'all three original deployment rules, both orders, both available regimes and both \'\n        \'pilot-selected static ranks. No new training, rate selection, or official-test access. \'\n        \'The learned routers have only final fixed-memory reload measurements; temporal \'\n        \'retention is unavailable for those rules and is not imputed.\', \'\',\n        \'Definitions: final concept-macro accuracy; the mean of five seen-concept checkpoint \'\n        \'accuracies; the maximum accuracy at checkpoints after a concept first finishes \'\n        \'training minus its final accuracy, averaged over concepts; and final minus \'\n        \'first-exposure accuracy, averaged over concepts. The last statistic includes \'\n        \'recurrence learning and is not standard nonrecurring-task backward transfer. \'\n        \'Positive maximum-checkpoint drop means more loss from the observed peak; positive \'\n        \'final-minus-first means improvement. The peak is a defined evaluation summary, \'\n        \'not a selected predictor. Checkpoints do not constitute independent samples.\', \'\',\n        \'## All paired comparisons\', \'\', markdown_table(summary), \'\',\n        \'All intervals are descriptive over training seeds with orders averaged first. \'\n        \'Fixed development examples were repeatedly examined. These secondary summaries \'\n        \'neither establish a formal protected-memory guarantee nor change the primary \'\n        \'final-accuracy selection objective.\', \'\']\n    Path(\'notes/day18_deployment_retention_results.md\').write_text(\'\\n\'.join(report) + \'\\n\')\n    Path(\'notes/day18_retention_source_receipt.json\').write_text(json.dumps({\n        \'source_files_sha256\': hashes, \'analysis_added_after_primary_outcomes\': True,\n        \'training_outputs_modified\': False, \'official_test_accessed\': False,\n        \'complete_trajectories\': len(rows)//3}, indent=2) + \'\\n\')\n    print(\'SECONDARY_DEPLOYED_RETENTION_SAVED\', len(rows)//3, \'trajectories\', len(summary), \'comparisons\', flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day18_retention_integrity.py': '"""Known recurrence curve checks, including exclusion of unseen predictions."""\nimport json\nfrom pathlib import Path\nimport tempfile\n\nimport numpy as np\nimport pandas as pd\nfrom experiments.day18_deployment_retention import summarize, RULES\n\n\ndef main():\n    with tempfile.TemporaryDirectory(prefix=\'retention_curve_integrity_\') as name:\n        folder = Path(name)\n        (folder/\'summary.json\').write_text(json.dumps({\'status\': \'completed\', \'steps\': 80}))\n        (folder/\'provenance.json\').write_text(\'{}\')\n        route = pd.DataFrame([{\'step\': i+1, \'segment\': [\'A1\',\'B1\',\'A2\',\'C1\',\'B2\'][i//16],\n                               \'concept\': [\'A\',\'B\',\'A\',\'C\',\'B\'][i//16]} for i in range(80)])\n        route.to_csv(folder/\'routing.csv\', index=False)\n        accuracies = {\'A\': [.5,.4,.7,.6,.6], \'B\': [.99,.6,.5,.5,.8], \'C\': [.95,.95,.95,.7,.5]}\n        rows = [{\'step\': 16*(j+1), \'checkpoint\': [\'A1\',\'B1\',\'A2\',\'C1\',\'B2\'][j],\n                 \'rule\': rule, \'concept\': concept, \'accuracy\': accuracies[concept][j], \'n\': 12,\n                 \'seen_concept\': concept in set(route.loc[route.step <= 16*(j+1), \'concept\'])}\n                for j in range(5) for rule in RULES for concept in [\'A\',\'B\',\'C\']]\n        frame = pd.DataFrame(rows)\n        frame.to_csv(folder/\'label_free_eval.csv\', index=False)\n        _, metrics, concepts = summarize(folder)\n        for row in metrics:\n            assert abs(row[\'final_macro_accuracy\'] - 1.9/3) < 1e-12\n            assert abs(row[\'mean_seen_checkpoint_accuracy\'] - (.5+.5+.6+.6+1.9/3)/5) < 1e-12\n            assert abs(row[\'maximum_seen_checkpoint_drop\'] - .1) < 1e-12\n            assert abs(row[\'final_minus_first_exposure\'] - .1/3) < 1e-12\n        assert len(concepts) == 9\n        for bad in [frame.iloc[:-1], frame.assign(seen_concept=True)]:\n            bad.to_csv(folder/\'label_free_eval.csv\', index=False)\n            try:\n                summarize(folder)\n            except AssertionError:\n                pass\n            else:\n                raise AssertionError(\'Incomplete or future-contaminated curve was accepted\')\n    print(\'RETENTION_CURVE_ANALYTIC_GATE_PASS recurrence, unseen exclusion, missing-data rejection\', flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n'}

from datetime import datetime,timezone
import fcntl,hashlib,json,os,subprocess,sys,time
from pathlib import Path
ROOT=Path('/workspace/mitosis-interference')
STAGE=Path('/workspace/mitosis-day15-stage')
ENV=os.environ.copy();ENV.update(GIT_TERMINAL_PROMPT='0',GH_PROMPT_DISABLED='1')
BRANCH='day5-causal-audit'
def read(args):return subprocess.check_output(args,cwd=ROOT,env=ENV,text=True,timeout=90).strip()
def run(args,log=None):
 print('RUN',' '.join(args),flush=True)
 return subprocess.run(args,cwd=ROOT,env=ENV,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT if log else None).returncode
os.chdir(ROOT)
locks=[open('/workspace/mitosis-restart-worker.lock','a'),open('/workspace/mitosis-static-tuning-worker.lock','a')]
while True:
 if datetime.now(timezone.utc)>=datetime.fromisoformat('2026-10-07T03:29:00+00:00'):raise RuntimeError('Evidence QC cutoff; staged source remains for the next session')
 acquired=[];ready=False
 try:
  for lock in locks:
   fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB);acquired.append(lock)
  p=Path('notes/day17_branch_integration.json')
  if p.exists():
   integration=json.loads(p.read_text())
   ready=integration.get('combined_remote_checkpoints_verified') and not integration.get('combined_save_pending') and not any(integration['editorial_returncodes'].values())
  if ready:break
 except BlockingIOError:pass
 finally:
  if not ready:
   for lock in acquired:fcntl.flock(lock,fcntl.LOCK_UN)
 print('EVIDENCE_QC_WAITING_FOR_VERIFIED_INTEGRATION',datetime.now(timezone.utc).isoformat(),flush=True)
 time.sleep(30)
assert read(['git','branch','--show-current'])==BRANCH
assert read(['git','remote','get-url','origin'])=='https://github.com/anitusiruk/mitosis-interference.git'
assert not read(['git','status','--porcelain'])
assert read(['git','rev-parse','HEAD'])==read(['git','ls-remote','origin','refs/heads/'+BRANCH]).split()[0]
checker=STAGE/'factorial_receipt_audit.py'
assert hashlib.sha256(checker.read_bytes()).hexdigest()=='be2bc41fe2af7f81792bb240037dd1abc8259b966d076a7d0d5e08d14d338521'
assert not Path('experiments/day18_factorial_receipt_audit.py').exists()
Path('experiments/day18_factorial_receipt_audit.py').write_bytes(checker.read_bytes())
for name,text in FILES.items():
 p=Path(name);assert not p.exists();p.write_text(text)
Path('experiments/day18_finalize_evidence_quality.py').write_bytes(Path(__file__).read_bytes())
for source,target in [('factorial_receipt_audit_first.json','notes/factorial_receipt_integrity_first.json'),('factorial_receipt_audit_first.log','logs/factorial_receipt_integrity_first.txt')]:
 assert not Path(target).exists();Path(target).write_bytes((STAGE/source).read_bytes())
with Path('logs/factorial_receipt_integrity_final.txt').open('x') as log:
 code=run([sys.executable,'-u','-m','experiments.day18_factorial_receipt_audit','--root',str(ROOT),'--output','notes/factorial_receipt_integrity_final.json'],log)
retention=None
with Path('logs/day18_retention_integrity.txt').open('x') as log:
 retention=run([sys.executable,'-u','-m','experiments.day18_retention_integrity'],log)
if retention==0:
 with Path('logs/day18_deployment_retention.txt').open('x') as log:
  retention=run([sys.executable,'-u','-m','experiments.day18_deployment_retention'],log)
editorial=None
if code==0 and retention==0:
 with Path('logs/day18_evidence_caveats.txt').open('x') as log:
  editorial=run([sys.executable,'-u','-m','experiments.day18_evidence_caveats'],log)
qc=json.loads(Path('notes/factorial_receipt_integrity_final.json').read_text())
receipt=json.loads(Path('notes/github_save_verification.json').read_text())
assert receipt['all_current_lfs_sha256_verified']
# Plain-text/figure edits do not change the checkpoint tree already freshly fetched.
changed=read(['git','diff','--name-only',receipt['preserved_snapshot_commit'],'HEAD']).splitlines()
assert not any('checkpoint' in Path(p).parts or Path(p).suffix in {'.pt','.safetensors'} for p in changed)
assert not any('checkpoint' in Path(p).parts or Path(p).suffix in {'.pt','.safetensors'} for p in read(['git','diff','--name-only']).splitlines())
status={'utc':datetime.now(timezone.utc).isoformat(),'quality_control_returncode':code,'editorial_returncode':editorial,'secondary_retention_returncode':retention,
 'verified_observers':len(qc['passed']),'planned_observers':20,'remaining_observers':20-len(qc['passed']),
 'fresh_remote_checkpoint_snapshot':receipt['preserved_snapshot_commit'],
 'checkpoint_tree_unchanged_since_verified_snapshot':True,'training_outputs_modified':False,
 'scope':'independent saved-receipt integrity and transparent manuscript estimands; scientific confirmation remains incomplete'}
Path('notes/final_evidence_quality_status.json').write_text(json.dumps(status,indent=2)+'\n')
assert run(['git','add','-A'])==0
assert run(['git','commit','-m','Verify every mature-batch factorial receipt and clarify evidence estimands'])==0
assert run(['git','push','origin',BRANCH])==0
head=read(['git','rev-parse','HEAD'])
assert read(['git','ls-remote','origin','refs/heads/'+BRANCH]).split()[0]==head
assert not read(['git','status','--porcelain'])
changed=read(['git','diff','--name-only',receipt['preserved_snapshot_commit'],head]).splitlines()
assert not any('checkpoint' in Path(p).parts or Path(p).suffix in {'.pt','.safetensors'} for p in changed)
print('POST_INTEGRATION_EVIDENCE_QC_AND_SAVE_COMPLETE',head,'QUALITY',code,'EDITORIAL',editorial,'RETENTION',retention,'OBSERVERS',len(qc['passed']),flush=True)
if code or editorial or retention:raise RuntimeError('Evidence discrepancy preserved for inspection')

